Here's a water tracker with a goal of 8 glasses. Tap + after each glass and it resets by itself each day.

```page
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<style>
  body { font-family: system-ui, sans-serif; text-align: center; padding: 24px; margin: 0; }
  h1 { font-size: 20px; margin: 0 0 4px; }
  .sub { color: #666; font-size: 13px; margin-bottom: 20px; }
  .count { font-size: 48px; font-weight: 600; margin: 8px 0; }
  .bar { height: 14px; background: #ddd; border-radius: 7px; overflow: hidden; margin: 12px auto; max-width: 320px; }
  .fill { height: 100%; width: 0; background: #2f8fd8; transition: width .3s; }
  .glasses { font-size: 26px; margin: 12px 0; min-height: 36px; letter-spacing: 2px; }
  button { font-size: 18px; padding: 10px 22px; margin: 4px; border-radius: 8px; border: 1px solid #999; background: #fff; cursor: pointer; }
  button.main { background: #2f8fd8; color: #fff; border-color: #2f8fd8; }
  .msg { margin-top: 14px; font-size: 15px; min-height: 20px; }
</style>
</head>
<body>
  <h1>Water today</h1>
  <div class="sub" id="date"></div>
  <div class="count"><span id="n">0</span> / 8</div>
  <div class="bar"><div class="fill" id="fill"></div></div>
  <div class="glasses" id="glasses"></div>
  <div>
    <button onclick="change(-1)">&minus;</button>
    <button class="main" onclick="change(1)">+ Add a glass</button>
  </div>
  <div><button onclick="reset()">Reset today</button></div>
  <div class="msg" id="msg"></div>
<script>
  var GOAL = 8;
  var today = new Date().toISOString().slice(0, 10);
  var key = "water-" + today;
  var count = 0;
  try { count = parseInt(localStorage.getItem(key), 10) || 0; } catch (e) {}

  function save() {
    try { localStorage.setItem(key, String(count)); } catch (e) {}
  }
  function change(d) {
    count = Math.max(0, count + d);
    save();
    render();
  }
  function reset() {
    count = 0;
    save();
    render();
  }
  function render() {
    document.getElementById("date").textContent = today;
    document.getElementById("n").textContent = count;
    document.getElementById("fill").style.width = Math.min(100, count / GOAL * 100) + "%";
    var g = "";
    for (var i = 0; i < Math.max(GOAL, count); i++) g += i < count ? "\uD83D\uDCA7" : "\u25CB";
    document.getElementById("glasses").textContent = g;
    var m = count >= GOAL ? "Goal reached. Nicely done!" : (GOAL - count) + " more to go.";
    document.getElementById("msg").textContent = m;
  }
  render();
</script>
</body>
</html>
```

